const linePath = vals => {
  const pts = vals.map((v,i)=>({x:x(i), y:y(v)}));
  if (!pts.length) return '';
  if (pts.length === 1) return `M ${pts[0].x.toFixed(1)} ${pts[0].y.toFixed(1)}`;
  const ds = [];
  for (let i=0; i<pts.length-1; i++) {
    ds.push((pts[i+1].y - pts[i].y) / Math.max(1, pts[i+1].x - pts[i].x));
  }
  const ms = pts.map((_, i) => {
    if (i === 0) return ds[0] * 0.65;
    if (i === pts.length - 1) return ds[ds.length - 1] * 0.65;
    if (ds[i-1] === 0 || ds[i] === 0 || Math.sign(ds[i-1]) !== Math.sign(ds[i])) return 0;
    return Math.sign(ds[i]) * Math.min(Math.abs(ds[i-1]), Math.abs(ds[i]), Math.abs((ds[i-1] + ds[i]) / 2)) * 0.65;
  });
  let dPath = `M ${pts[0].x.toFixed(1)} ${pts[0].y.toFixed(1)}`;
  for (let i=0; i<pts.length-1; i++) {
    const p0 = pts[i], p1 = pts[i+1];
    const dx = p1.x - p0.x;
    const c1x = p0.x + dx / 3;
    const c1y = p0.y + ms[i] * dx / 3;
    const c2x = p1.x - dx / 3;
    const c2y = p1.y - ms[i+1] * dx / 3;
    dPath += ` C ${c1x.toFixed(1)} ${c1y.toFixed(1)}, ${c2x.toFixed(1)} ${c2y.toFixed(1)}, ${p1.x.toFixed(1)} ${p1.y.toFixed(1)}`;
  }
  return dPath;
};
